CREATE FUNCTION public.portal_ensure_first_receipt_date() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.form_key='item23' AND NEW.correction_request_id IS NULL THEN INSERT INTO public.candidate_compliance(candidate_id,fdd_received_at) VALUES(NEW.candidate_id,NEW.signed_at) ON CONFLICT(candidate_id) DO NOTHING; UPDATE public.candidate_compliance SET fdd_received_at=NEW.signed_at WHERE candidate_id=NEW.candidate_id AND fdd_received_at IS NULL; END IF; RETURN NEW; END $$;
CREATE TRIGGER ensure_original_receipt_date AFTER INSERT ON public.candidate_portal_signatures FOR EACH ROW EXECUTE FUNCTION public.portal_ensure_first_receipt_date();